B.bsi=new A.dK("Questo evento \xe8 stato annullato da chi lo organizzava. Se avevi comprato un biglietto, il rimborso \xe8 gi\xe0 partito.",B.eq,B.bn,null)
B.btH=new A.H(B.dQ,B.bsi,null)
